import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for eid in [1, 3, 9, 10]:
    try:
        path = eval(f"experiment_{eid}_csv")
        df = pd.read_csv(path)
        df['experiment_id'] = eid
        dfs[eid] = df
        print(f"Experiment {eid}: n={len(df)}, cols={list(df.columns)}")
        print(f"  JobThroughput mean={df['JobThroughput'].mean():.3f}, SD={df['JobThroughput'].std():.3f}")
        if 'CoolingAggressiveness' in df.columns:
            print(f"  CoolingAggressiveness: {df['CoolingAggressiveness'].unique()}")
        if 'RackInletTemp' in df.columns:
            print(f"  RackInletTemp mean={df['RackInletTemp'].mean():.3f}")
        if 'FanSpeed' in df.columns:
            print(f"  FanSpeed mean={df['FanSpeed'].mean():.3f}")
        print()
    except Exception as e:
        print(f"Experiment {eid} error: {e}")
